const std = @import("std");

// Sacred-only imports (L0 — always compiles)
const trinity_workspace = @import("trinity_workspace.zig");
const tri_utils = @import("tri_utils.zig");
const tri_config = @import("tri_config.zig");

pub fn main() !void {
    trinity_workspace.cdToRepoRootSilent();

    const allocator = std.heap.page_allocator;
    const args = try std.process.argsAlloc(allocator);
    defer std.process.argsFree(allocator, args);

    if (args.len < 2) {
        std.debug.print("L0 Temple: sacred core initialized\n", .{});
        std.debug.print("Usage: temple_exe <command> [args...]\n", .{});
        std.debug.print("\nL0 Temple Commands:\n", .{});
        std.debug.print("  status    — Show Trinity workspace status\n", .{});
        std.debug.print("  cd       — Change to repository root\n", .{});
        std.debug.print("  help      — Show this help\n", .{});
        return;
    }

    const cmd = args[1];
    const cmd_args = args[2..];

    // Only core commands available in L0
    if (std.mem.eql(u8, cmd, "status")) {
        try tri_utils.runStatusCommand(allocator, cmd_args);
    } else if (std.mem.eql(u8, cmd, "cd")) {
        try trinity_workspace.cdToRepoRoot(allocator, cmd_args);
    } else if (std.mem.eql(u8, cmd, "help")) {
        printHelp();
    } else {
        std.debug.print("[L0 TEMPLE] Unknown command: {s}\n", .{cmd});
        std.debug.print("Available: status, cd, help\n", .{});
        return error.UnknownCommand;
    }
}

fn printHelp() void {
    std.debug.print("\nL0 TEMPLE — Sacred Core\n", .{});
    std.debug.print("═════════════════════════\n", .{});
    std.debug.print("\nThis is the minimal Trinity core that always compiles.\n", .{});
    std.debug.print("It only imports sacred modules (trinity_workspace, tri_utils).\n", .{});
    std.debug.print("\nCommands:\n", .{});
    std.debug.print("  status    Show Trinity workspace status\n", .{});
    std.debug.print("  cd       Change to repository root\n", .{});
    std.debug.print("  help      Show this help\n", .{});
    std.debug.print("\n", .{});
}
